from pathlib import Path
import json,re,collections
R=Path(__file__).resolve().parents[4]; O=Path(__file__).resolve().parent.parent; E=O/'evidence'
inv=json.loads((E/'inventory.json').read_text())
def cite(path,line=1):
 return f'[{path}:{line}](../../../{path}#L{line})'
def match(path,needle):
 lines=(R/path).read_text().splitlines()
 for i,s in enumerate(lines,1):
  if needle in s:return cite(path,i)
 raise ValueError((path,needle))
def sk(name):return next(x['path'] for x in inv if x['frontmatter']['name']==name)
def s(name,needle):return match(sk(name),needle)
def write(name,text): (O/name).write_text(text.strip()+'\n')
